query:
query SimulcastHorseProfile($ids: [String!], $meetingDate: String, $raceNumber: String) {
  simulcastHorse(ids: $ids, meetingDate: $meetingDate, raceNumber: $raceNumber) {
    age
    brandNumber
    earings
    colour {
      code
      chinese
      english
    }
    dam
    countryOfOrigin {
      chinese
      code
      english
    }
    sire
    sireOfDam
    rating
    name_ch
    name_en
    gender {
      chinese
      code
      english
    }
    id
    trainer {
      name_ch
      name_en
    }
    ownerName {
      chinese
      code
      english
    }
    winningRecord {
      totalStakes
      firstPlace
      secondPlace
      thirdPlace
      totalRun
    }
    performanceStats {
      type
      firstPlace
      secondPlace
      thirdPlace
      totalRun
      ssn
    }
    horseFormRecord {
      id
    }  
  }
}
